<?php
$n = (int)trim(fgets(STDIN));

// A number is "undoubtedly lucky" if its decimal representation contains at most 2 distinct digits.
// We need to count all positive integers <= n that have at most 2 distinct digits.

// Approach:
// For each number from 1 to n, check if it has at most 2 distinct digits.
// But n can be up to 10^9, so we can't iterate through all numbers.

// Better approach:
// Count all numbers with at most 2 distinct digits up to n.
// We can use digit DP or generate all such numbers.

// Since a number with at most 2 distinct digits can be generated by choosing 2 digits (or 1 digit) and forming numbers with those digits.
// But we need to count only those <= n.

// Alternative: Use inclusion-exclusion or direct counting.

// Let's think differently:
// Total numbers from 1 to n is n.
// Subtract numbers that have 3 or more distinct digits.

// But it's easier to count numbers with at most 2 distinct digits directly.

// We can iterate over all possible pairs of digits (including single digit cases) and count how many numbers formed by these digits are <= n.
// But we need to be careful not to double count.

// Actually, let's use a different approach:
// For each number, the set of distinct digits has size 1 or 2.
// We can count:
// 1. Numbers with exactly 1 distinct digit (repdigits)
// 2. Numbers with exactly 2 distinct digits

// But counting numbers with exactly 2 distinct digits <= n is tricky.

// Let's use digit DP.
// State: position, tight, started, set of digits used (as a bitmask of 10 bits)
// But the set of digits used can be represented as a bitmask of 10 bits, which is 2^10 = 1024 states.
// Position: up to 10 digits (since n <= 10^9, so at most 10 digits)
// Tight: 2 states
// Started: 2 states
// Total states: 10 * 2 * 2 * 1024 = 40960, which is manageable.

// Let's implement digit DP.

function countUndoubtedlyLucky($n) {
    $digits = str_split(strval($n));
    $len = count($digits);

    // dp[pos][tight][started][mask]
    // pos: current position (0 to len)
    // tight: whether we are still matching the prefix of n
    // started: whether we have started the number (to handle leading zeros)
    // mask: bitmask of digits used so far

    // We'll use memoization
    $memo = [];

    function dfs($pos, $tight, $started, $mask, $digits, $len, &$memo) {
        if ($pos == $len) {
            if (!$started) return 0; // no number formed
            // Check if mask has at most 2 bits set
            $count = 0;
            $m = $mask;
            while ($m > 0) {
                if ($m & 1) $count++;
                $m >>= 1;
            }
            return $count <= 2 ? 1 : 0;
        }

        $key = "$pos|$tight|$started|$mask";
        if (isset($memo[$key])) {
            return $memo[$key];
        }

        $limit = $tight ? $digits[$pos] : 9;
        $result = 0;

        for ($d = 0; $d <= $limit; $d++) {
            $newTight = $tight && ($d == $limit);
            $newStarted = $started || ($d != 0);
            $newMask = $mask;
            if ($newStarted) {
                $newMask |= (1 << $d);
            }

            // If we haven't started and d==0, we continue without starting
            if (!$started && $d == 0) {
                $result += dfs($pos + 1, $newTight, false, 0, $digits, $len, $memo);
            } else {
                $result += dfs($pos + 1, $newTight, $newStarted, $newMask, $digits, $len, $memo);
            }
        }

        $memo[$key] = $result;
        return $result;
    }

    return dfs(0, true, false, 0, $digits, $len, $memo);
}

echo countUndoubtedlyLucky($n);
