function isUndoubtedlyLucky($num) {
    $digits = [];
    $n = $num;
    while ($n > 0) {
        $digits[] = $n % 10;
        $n = intdiv($n, 10);
    }
    $uniqueDigits = array_unique($digits);
    $count = count($uniqueDigits);
    if ($count <= 2) {
        return true;
    }
    return false;
}

